import { Component, computed, inject, input, signal, viewChild } from '@angular/core';
import { MoneyPipe } from '../currencies/money.pipe';
import { rxResource } from '@angular/core/rxjs-interop';
import { Router, RouterLink } from '@angular/router';
import { ClientContacts } from '../contacts/client-contacts';
import { Contact } from '../contacts/contact.service';
import { ClientCredit } from '../credit/client-credit';
import { ClientDeposits } from '../deposits/client-deposits';
import { ClientPaymentForm, PaymentSource } from '../payments/client-payment';
import { ClientProjects } from '../projects/client-projects';
import { ClientCurrency } from './client-currency';
import { ClientExport } from './client-export';
import { ClientMerge } from './client-merge';
import { Client, ClientService } from './client.service';

// A single client's page: their name, email, phone number, tax number, billing address, main contact and currency, an export of their contact details to a file, a link to their statement, a form to record a lump payment split across their invoices or to put their held deposits toward those invoices the same way, the credit they have to spend (unused deposits and credit notes) with a form to refund it, the deposits they have paid up front, counts of their projects and contacts, the total ever billed to them, their contacts, the projects being done for them, and a form to merge this client into a duplicate of it.
@Component({
  selector: 'app-client-detail',
  imports: [MoneyPipe, RouterLink, ClientCurrency, ClientContacts, ClientProjects, ClientPaymentForm, ClientDeposits, ClientCredit, ClientMerge, ClientExport],
  styles: `
    .client-badges {
      display: flex;
      gap: 1rem;
      padding: 0;
      list-style: none;
    }
    .client-billing-address {
      white-space: pre-line;
    }
  `,
  template: `
    <a routerLink="/clients" data-testid="client-back">Back to clients</a>
    @if (client.error()) {
      <p role="alert" data-testid="client-error">Could not load the client.</p>
    } @else if (client.value(); as c) {
      <h1 data-testid="client-detail-name">{{ c.name }}</h1>
      <p>Email: <span data-testid="client-detail-email">{{ c.email }}</span></p>
      <p>
        Phone:
        @if (c.phone) {
          <a [href]="'tel:' + c.phone" data-testid="client-phone">{{ c.phone }}</a>
        } @else {
          <span data-testid="client-phone-none">Not given</span>
        }
      </p>
      <p>
        Tax number:
        @if (c.taxNumber) {
          <span data-testid="client-tax-number">{{ c.taxNumber }}</span>
        } @else {
          <span data-testid="client-tax-number-none">Not tax registered</span>
        }
      </p>
      <p>
        Billing address:
        @if (c.billingAddress) {
          <span class="client-billing-address" data-testid="client-billing-address">{{ c.billingAddress }}</span>
        } @else {
          <span data-testid="client-billing-address-none">Not given</span>
        }
      </p>
      <p>
        Prices: <span data-testid="client-tax-mode">{{ c.taxInclusive ? 'Include tax' : 'Tax added on' }}</span>
      </p>
      <p>
        Tax exempt: <span data-testid="client-tax-exempt">{{ c.taxExempt ? 'Yes' : 'No' }}</span>
      </p>
      <p>
        Key account: <span data-testid="client-key-account-flag">{{ c.keyAccount ? 'Yes' : 'No' }}</span>
      </p>
      <p>
        Standard discount: <span data-testid="client-default-discount">{{ c.defaultDiscountPct > 0 ? c.defaultDiscountPct + '%' : 'None' }}</span>
      </p>
      <p>
        Main contact:
        @if (c.primaryContact; as primary) {
          <span data-testid="client-primary-contact">{{ primary.name }}</span>
        } @else {
          <span data-testid="client-primary-contact-none">None chosen</span>
        }
      </p>
      <app-client-export [clientId]="clientId()" />
      <app-client-currency [client]="c" (changed)="currencyChanged($event)" />
      @if (summary.hasValue()) {
        <ul class="client-badges" aria-label="At a glance" data-testid="client-badges">
          <li>
            Jobs: <span data-testid="client-projects-count">{{ summary.value().projectCount }}</span>
          </li>
          <li>
            Contacts: <span data-testid="client-contacts-count">{{ summary.value().contactCount }}</span>
          </li>
          <li>
            Billed to date:
            <span data-testid="client-lifetime-billed">{{
              summary.value().lifetimeBilled | money: c.currency
            }}</span>
          </li>
        </ul>
      }
      <p>
        <a [routerLink]="['/clients', clientId(), 'statement']" data-testid="client-statement-open">View statement</a>
      </p>
      <p>
        <button
          type="button"
          data-testid="client-record-payment"
          aria-controls="client-payment-panel"
          [attr.aria-expanded]="recordingPayment() === 'payment'"
          (click)="toggle('payment')"
        >
          {{ recordingPayment() === 'payment' ? 'Close payment form' : 'Record a payment' }}
        </button>
        <button
          type="button"
          data-testid="client-allocate-deposit"
          aria-controls="client-payment-panel"
          [attr.aria-expanded]="recordingPayment() === 'deposit'"
          (click)="toggle('deposit')"
        >
          {{ recordingPayment() === 'deposit' ? 'Close deposit form' : 'Put a deposit toward invoices' }}
        </button>
      </p>
      <div id="client-payment-panel">
        @if (recordingPayment(); as source) {
          <app-client-payment [clientId]="clientId()" [source]="source" (recorded)="paymentRecorded(source)" />
        }
        @if (paymentSaved()) {
          <p role="status" data-testid="client-payment-recorded">Payment recorded.</p>
        }
        @if (depositApplied()) {
          <p role="status" data-testid="client-deposit-applied">Deposit applied.</p>
        }
      </div>
      <app-client-credit [clientId]="clientId()" [currency]="c.currency" (refunded)="creditRefunded()" />
      <app-client-deposits [clientId]="clientId()" [currency]="c.currency" />
      <app-client-contacts
        [clientId]="clientId()"
        (contactAdded)="contactAdded()"
        (primaryChanged)="primaryChanged($event)"
      />
      <app-client-projects [clientId]="clientId()" />
      <app-client-merge [client]="c" (merged)="clientMerged($event)" />
    }
  `,
})
export class ClientDetail {
  private readonly service = inject(ClientService);
  private readonly router = inject(Router);

  /** Bound from the `:id` route parameter. */
  readonly id = input.required<string>();
  protected readonly clientId = computed(() => Number(this.id()));

  protected readonly client = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.get(params),
  });

  protected readonly summary = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.summary(params),
  });

  /** Which split form is open, if any: a payment received, or the client's held deposits. */
  protected readonly recordingPayment = signal<PaymentSource | null>(null);
  protected readonly paymentSaved = signal(false);
  protected readonly depositApplied = signal(false);
  private readonly paymentForm = viewChild(ClientPaymentForm);
  private readonly depositsPanel = viewChild(ClientDeposits);
  private readonly creditPanel = viewChild(ClientCredit);
  private readonly mergePanel = viewChild(ClientMerge);
  /** Set once the page is being left, so a merge finishing meanwhile does not pull the user back. */
  private leaving = false;

  /** Resolves to true once any payment being recorded, or merge under way, has finished, so the page can be left safely. */
  async canLeave(): Promise<boolean> {
    this.leaving = true;
    await Promise.all([this.paymentForm()?.settled(), this.mergePanel()?.settled()]);
    this.leaving = false;
    return true;
  }

  protected toggle(source: PaymentSource): void {
    this.recordingPayment.update((open) => (open === source ? null : source));
  }

  protected paymentRecorded(source: PaymentSource): void {
    this.recordingPayment.set(null);
    this.paymentSaved.set(source === 'payment');
    this.depositApplied.set(source === 'deposit');
    // A payment may use up the client's credit or leave some over as credit, so both panels can change.
    this.depositsPanel()?.reload();
    this.creditPanel()?.reload();
    this.client.reload();
  }

  protected creditRefunded(): void {
    this.depositsPanel()?.reload();
  }

  protected contactAdded(): void {
    this.summary.reload();
    // The first contact added becomes the main contact.
    if (!this.client.value()?.primaryContact) {
      this.client.reload();
    }
  }

  protected currencyChanged(client: Client): void {
    this.client.set(client);
  }

  protected clientMerged(kept: Client): void {
    // This client no longer exists; carry on at the one it was merged into, unless the user is already leaving.
    if (this.leaving) {
      return;
    }
    void this.router.navigate(['/clients', kept.id]);
  }

  protected primaryChanged(contact: Contact): void {
    this.client.update((c) => c && { ...c, primaryContact: { id: contact.id, name: contact.name } });
  }
}
import { Component, computed, inject, input, signal } from '@angular/core';
import { MoneyPipe } from '../currencies/money.pipe';
import { rxResource } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { InvoiceService } from './invoice.service';

// A client's statement: every invoice across the client's projects grouped by job, how much is left to
// pay on each, a subtotal still owed and the tax per job, the tax across the statement, and the total the client still owes. Drafts are listed but do not count towards what is owed.
// The balance owed as at a chosen past date can be looked up, counting only entries up to that date.
// It opens with the running account: invoices, payments, credit notes, deposits and refunds in date order with the
// balance owed after each.
// It is laid out to print cleanly: a summary of what was invoiced, what was paid and the grand total owed,
// with the app's navigation and the page's controls left off the printed copy.
@Component({
  selector: 'app-client-statement',
  imports: [MoneyPipe, RouterLink],
  styles: `
    .statement-actions {
      display: flex;
      gap: 1rem;
      align-items: center;
    }
    .statement-summary {
      display: grid;
      grid-template-columns: max-content max-content;
      gap: 0.25rem 1.5rem;
    }
    .statement-summary dd {
      margin: 0;
      text-align: right;
    }
    .statement-grand-total {
      font-weight: bold;
      border-top: 1px solid currentColor;
      padding-top: 0.25rem;
    }
    table {
      border-collapse: collapse;
    }
    .statement-money {
      text-align: right;
    }
    th,
    td {
      padding: 0.25rem 0.5rem;
      text-align: left;
    }
    @media print {
      .statement-actions {
        display: none;
      }
      table {
        width: 100%;
      }
      tbody {
        break-inside: avoid;
      }
    }
  `,
  template: `
    <div class="statement-actions">
      <a [routerLink]="['/clients', clientId()]" data-testid="client-statement-back">Back to client</a>
      @if (statement.hasValue()) {
        <button type="button" data-testid="statement-print" (click)="print()">Print statement</button>
      }
    </div>
    @if (statement.error()) {
      <p role="alert" data-testid="client-statement-error">Could not load the statement.</p>
    } @else if (statement.value(); as s) {
      <article data-testid="statement-print-view" aria-labelledby="statement-heading">
        <h1 id="statement-heading" data-testid="client-statement-name">Statement for {{ s.clientName }}</h1>
        <section aria-labelledby="statement-summary-heading" data-testid="statement-summary">
          <h2 id="statement-summary-heading">Summary</h2>
          <dl class="statement-summary">
            <dt>Total invoiced</dt>
            <dd data-testid="statement-total-invoiced">{{ s.invoiced | money: s.currency }}</dd>
            <dt>Tax</dt>
            <dd data-testid="client-statement-tax-total">{{ s.tax | money: s.currency }}</dd>
            <dt>Less paid</dt>
            <dd data-testid="statement-total-paid">{{ s.paid | money: s.currency }}</dd>
            <dt class="statement-grand-total">Grand total owed</dt>
            <dd class="statement-grand-total" data-testid="statement-grand-total">{{ s.outstanding | money: s.currency }}</dd>
          </dl>
        </section>
        <section aria-labelledby="statement-asof-heading" data-testid="statement-asof">
          <h2 id="statement-asof-heading">Balance as at a date</h2>
          <form class="statement-actions" (submit)="applyAsOf($event, asOfInput.value)">
            <label for="statement-asof-date">As at</label>
            <input #asOfInput id="statement-asof-date" type="date" required data-testid="statement-asof-date" />
            <button type="submit" data-testid="statement-asof-apply">Show balance</button>
          </form>
          @if (balanceAsOf.error()) {
            <p role="alert" data-testid="client-balance-asof-error">Could not load the balance.</p>
          } @else if (balanceAsOf.value(); as b) {
            <p aria-live="polite">
              Owed as at {{ b.asOf }}:
              <strong data-testid="client-balance-asof">{{ b.balance | money: b.currency }}</strong>
            </p>
          }
        </section>
        <section aria-labelledby="statement-account-heading" data-testid="statement-account">
          <h2 id="statement-account-heading">Account</h2>
          @if (s.entries.length === 0) {
            <p data-testid="statement-account-empty">Nothing on the account yet.</p>
          } @else {
            <table data-testid="statement-account-table">
              <caption>Running account for {{ s.clientName }}</caption>
              <thead>
                <tr>
                  <th scope="col">Date</th>
                  <th scope="col">Entry</th>
                  <th scope="col" class="statement-money">Charges</th>
                  <th scope="col" class="statement-money">Credits</th>
                  <th scope="col" class="statement-money">Balance</th>
                </tr>
              </thead>
              <tbody>
                @for (e of s.entries; track e.kind + e.sourceId; let n = $index) {
                  <tr [attr.data-testid]="'statement-entry-row-' + (n + 1)" [attr.data-kind]="e.kind">
                    <td data-testid="statement-entry-date">{{ e.date }}</td>
                    <td data-testid="statement-entry-description">{{ e.description }}</td>
                    <td class="statement-money" data-testid="statement-entry-charge">
                      @if (e.charge !== null) {
                        {{ e.charge | money: s.currency }}
                      }
                    </td>
                    <td class="statement-money" data-testid="statement-entry-credit">
                      @if (e.credit !== null) {
                        {{ e.credit | money: s.currency }}
                      }
                    </td>
                    <td class="statement-money" data-testid="statement-running-balance">{{ e.balance | money: s.currency }}</td>
                  </tr>
                }
              </tbody>
            </table>
          }
        </section>
        @if (s.invoices.length === 0) {
          <p data-testid="client-statement-empty">No invoices yet.</p>
        } @else {
          <table data-testid="client-statement-table">
            <caption>Invoices for {{ s.clientName }}</caption>
            <thead>
              <tr>
                <th scope="col">Invoice</th>
                <th scope="col">Job</th>
                <th scope="col">Status</th>
                <th scope="col">Issued</th>
                <th scope="col">Due</th>
                <th scope="col">Amount</th>
                <th scope="col">Tax</th>
                <th scope="col">Left to pay</th>
              </tr>
            </thead>
            @for (job of s.jobs; track job.projectId) {
              <tbody [attr.data-testid]="'statement-project-' + job.projectId">
                <tr>
                  <th scope="colgroup" colspan="8" data-testid="statement-project-name">{{ job.projectName }}</th>
                </tr>
                @for (i of job.invoices; track i.id) {
                  <tr [attr.data-testid]="'statement-invoice-row-' + i.id">
                    <td data-testid="statement-invoice-id">
                      <a
                        [routerLink]="['/projects', i.projectId, 'invoices', i.id]"
                        [attr.data-testid]="'statement-invoice-open-' + i.id"
                        [attr.aria-label]="'Open invoice #' + i.id"
                        >#{{ i.id }}</a
                      >
                    </td>
                    <td data-testid="statement-invoice-project">{{ i.projectName }}</td>
