          [attr.aria-expanded]="recordingPayment() === 'payment'"
          (click)="toggle('payment')"
        >
          {{ recordingPayment() === 'payment' ? 'Close payment form' : 'Record a payment' }}
        </button>
        <button
          type="button"
          data-testid="client-allocate-deposit"
