        return found.isEmpty() ? Map.of()
                : creditNotes.sumAmountByInvoiceIds(found.stream().map(Invoice::getId).toList()).stream()
                        .collect(Collectors.toMap(CreditNoteRepository.InvoiceCreditedTotal::getInvoiceId,
